package plates.ui

import plates.core.input.PlateController
import plates.core.theme.PlateTheme
import plates.core.values.PlateCountry
import plates.core.values.PlateSpec
import plates.core.values.PlateType

/** Turns a package asset (a flag, a decal) into a URL. */
public typealias AssetResolver = (packageName: String, path: String) -> String

/** Assets served from `packages/<package>/<path>`, the layout the country artifacts ship. */
public val defaultAssetResolver: AssetResolver = { p, a -> "packages/$p/$a" }

/** The slot values in order, empty slots skipped. */
public fun plateText(values: List<String?>): String = values.filterNot { it.isNullOrEmpty() }.joinToString("")

/**
 * A read-only plate as a standalone `<svg>` string; needs no browser, so it serves from a JVM backend as is.
 *
 * @param emptySvg returned instead of an empty plate when no slot holds a character.
 */
public fun renderPlateSvg(
    spec: PlateSpec,
    values: List<String?>,
    theme: PlateTheme? = null,
    country: PlateCountry? = null,
    emptySvg: String? = null,
    resolveAsset: AssetResolver = defaultAssetResolver,
): String {
    if (emptySvg != null && values.all { it.isNullOrEmpty() }) return emptySvg
    return PlateCanvas(spec, PlateController(spec, values), theme = theme, country = country).svg(resolveAsset)
}

/** [type] painted in its own livery, holding [values] (its sample when omitted). */
public fun renderPlateSvg(
    type: PlateType,
    values: List<String?> = type.sampleValues,
    resolveAsset: AssetResolver = defaultAssetResolver,
): String = renderPlateSvg(type.spec, values, type.theme, type.country, resolveAsset = resolveAsset)
